import{_ as a,o as n,a as p,b as c}from"./app.DKoEZOcr.js";const l="/ascendc.github.io/pr/5487/assets/reg_vector_overview.B7j7xuJn.png",w=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"Reg矢量计算","link":"/api/SIMD-API/basic_api/reg_vector_compute/reg_vector_compute"},{"text":"概述","link":"/api/SIMD-API/basic_api/reg_vector_compute/overview"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/reg_vector_compute/overview.md","filePath":"api/SIMD-API/basic_api/reg_vector_compute/overview.md","outlineHeaders":[{"level":2,"title":"如何使用Reg矢量计算API","slug":"如何使用Reg矢量计算API","link":"#如何使用Reg矢量计算API"},{"level":2,"title":"Reg矢量计算编程示例","slug":"Reg矢量计算编程示例","link":"#Reg矢量计算编程示例"}],"lastUpdated":1787050286000}'),e={name:"api/SIMD-API/basic_api/reg_vector_compute/overview.md"};function t(o,s,r,i,d,g){return n(),p("div",null,[...s[0]||(s[0]=[c('<div><article class="markdown-body"><h1>概述</h1><p>Reg矢量计算API是面向Reg矢量计算架构开发的API，用户可以通过该API直接对芯片中涉及Vector计算的寄存器进行操作，实现更大的灵活性和更好的性能。Reg矢量计算API与Memory矢量计算API功能相似，但与Memory矢量计算API输入和输出数据必须为LocalTensor不同，Reg矢量计算API的输入或输出数据均为Reg矢量计算寄存器。对于计算类API，其功能是从给定的寄存器获取数据，进行计算，并将结果保存在给定的寄存器。对于搬运类API，其功能是实现Unified Buffer（UB）和寄存器的数据搬运。由此可见，Reg矢量计算API相较于Memory矢量计算API，将数据搬运和Reg计算过程交给用户自主控制，从而实现更大的开发自由度。</p><h2 id="如何使用Reg矢量计算API">如何使用Reg矢量计算API<a class="header-anchor" href="#如何使用Reg矢量计算API">​</a></h2><p>基于寄存器的编程模型是指将数据从LocalTensor通过Reg搬运指令（Reg数据搬入）加载到寄存器中，进行复杂的数学计算Compute后通过Reg搬运指令（Reg数据搬出）搬出到LocalTensor中，所有的计算逻辑均在寄存器中完成，从而减少LocalTensor间的数据搬运，大大提升了整体性能，具体流程如下所示：</p><p><strong>图1</strong> Reg矢量计算<br><img src="'+l+`" alt title="Reg矢量计算"></p><p>以<a href="#reg%E7%9F%A2%E9%87%8F%E8%AE%A1%E7%AE%97%E7%BC%96%E7%A8%8B%E7%A4%BA%E4%BE%8B">Reg矢量计算编程示例</a>为例，完整的VectorFunction计算过程由以下几部分组成：</p><ul><li>编写和调用VectorFunction（向量函数）。这些函数使用__simd_vf__标记，通过<a href="./vf_call/asc_vf_call.html">asc_vf_call</a>被调用；</li><li>定义矢量数据寄存器<a href="./register_data_types/RegTensor.html">RegTensor</a>、掩码寄存器<a href="./register_data_types/MaskReg.html">MaskReg</a>；</li><li>编写for循环映射到硬件循环（<a href="./key_features/key_features.html#%E7%A1%AC%E4%BB%B6%E5%BE%AA%E7%8E%AFhardwareloop">HardwareLoop</a>）；<a href="./register_data_types/MaskReg.html#mask%E8%AE%BE%E7%BD%AE%E6%96%B9%E5%BC%8F">UpdateMask</a>函数用于更新参与计算的mask，每次循环都会消耗一个VL长度的元素。</li><li>循环内调用Reg数据搬入接口连续对齐搬入（<a href="./reg_data_load/LoadAlign_continuous.html">LoadAlign</a>）从UB中搬入单个VL长度数据；</li><li>循环内调用Reg计算接口Add完成单次Repeat计算；</li><li>循环内调用Reg数据搬出接口连续对齐搬出（<a href="./reg_data_store/StoreAlign_continuous.html">StoreAlign</a>）往UB中搬出计算后的数据；</li></ul><h2 id="Reg矢量计算编程示例">Reg矢量计算编程示例<a class="header-anchor" href="#Reg矢量计算编程示例">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="o">&gt;</span>
<span class="n">__simd_vf__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">AddVF</span><span class="p">(</span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">T</span><span class="o">*</span><span class="w"> </span><span class="n">dstAddr</span><span class="p">,</span><span class="w"> </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">T</span><span class="o">*</span><span class="w"> </span><span class="n">src0Addr</span><span class="p">,</span><span class="w"> </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">T</span><span class="o">*</span><span class="w"> </span><span class="n">src1Addr</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">count</span><span class="p">,</span><span class="w"> </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">oneRepeatSize</span><span class="p">,</span><span class="w"> </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">repeatTimes</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">RegTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="w"> </span><span class="n">srcReg0</span><span class="p">;</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">RegTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="w"> </span><span class="n">srcReg1</span><span class="p">;</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">RegTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="w"> </span><span class="n">dstReg</span><span class="p">;</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">MaskReg</span><span class="w"> </span><span class="n">mask</span><span class="p">;</span>
<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">repeatTimes</span><span class="p">;</span><span class="w"> </span><span class="o">++</span><span class="n">i</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">mask</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">UpdateMask</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="p">(</span><span class="n">count</span><span class="p">);</span>
<span class="w">        </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">LoadAlign</span><span class="p">(</span><span class="n">srcReg0</span><span class="p">,</span><span class="w"> </span><span class="n">src0Addr</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">oneRepeatSize</span><span class="p">);</span>
<span class="w">        </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">LoadAlign</span><span class="p">(</span><span class="n">srcReg1</span><span class="p">,</span><span class="w"> </span><span class="n">src1Addr</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">oneRepeatSize</span><span class="p">);</span>
<span class="w">        </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">Add</span><span class="p">(</span><span class="n">dstReg</span><span class="p">,</span><span class="w"> </span><span class="n">srcReg0</span><span class="p">,</span><span class="w"> </span><span class="n">srcReg1</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
<span class="w">        </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">StoreAlign</span><span class="p">(</span><span class="n">dstAddr</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">oneRepeatSize</span><span class="p">,</span><span class="w"> </span><span class="n">dstReg</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>

<span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">Compute</span><span class="p">()</span>
<span class="p">{</span>
<span class="w">    </span><span class="c1">// GM数据搬运至UB地址src0Addr及src1Addr</span>
<span class="w">    </span><span class="p">...</span>
<span class="w">    </span><span class="c1">// 调用vf函数</span>
<span class="w">    </span><span class="n">asc_vf_call</span><span class="o">&lt;</span><span class="n">AddVF</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&gt;</span><span class="p">(</span><span class="n">dstAddr</span><span class="p">,</span><span class="w"> </span><span class="n">src0Addr</span><span class="p">,</span><span class="w"> </span><span class="n">src1Addr</span><span class="p">,</span><span class="w"> </span><span class="n">count</span><span class="p">,</span><span class="w"> </span><span class="n">oneRepeatSize</span><span class="p">,</span><span class="w"> </span><span class="n">repeatTimes</span><span class="p">);</span>
<span class="w">    </span><span class="c1">// UB地址dstAddr数据搬运至GM</span>
<span class="w">    </span><span class="p">...</span>
<span class="p">}</span>
</code></pre></div><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><ul><li>GM与UB间的数据搬运需通过<a href="../memory_vector_compute/data_move/data_move.html">GM与UB数据搬运</a>完成；</li><li>Vector Function的流水类型为PIPE_V，Vector Function内部的同步依赖通过<a href="./sync_control/LocalMemBar.html">LocalMemBar</a>接口插入。</li></ul></div></article></div>`,1)])])}const A=a(e,[["render",t]]);export{w as __pageData,A as default};
